"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[8276],{1371(e){e.exports=JSON.parse('{"title":"Compound \ud328\ud134 type-safe\ud558\uac8c \ub9cc\ub4e4\uae30","date":"2026-01-13","coverUrl":"/kudzu-based-bench/assets/notion/16b38bc8c32fc822.png","html":"<h1 data-notion-block-id=\\"2dbe548d-8a8e-8053-b179-d52ff9395668\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"2e6e548d-8a8e-80c7-9e9b-f4f9d6d385b9\\" id=\\"2e6e548d-8a8e-80c7-9e9b-f4f9d6d385b9\\">Compound \ud328\ud134 type-safe\ud558\uac8c \ub9cc\ub4e4\uae30</h2><a href=\\"https://tkdodo.eu/blog/building-type-safe-compound-components\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tkdodo.eu/blog/building-type-safe-compound-components</a><p data-notion-block-id=\\"2e6e548d-8a8e-807c-a2e2-cd86993a61ce\\"><a href=\\"https://rosetta.page/post/%EB%B2%88%EC%97%AD-%ED%83%80%EC%9E%85-%EC%84%B8%EC%9D%B4%ED%94%84%ED%95%9C-%ED%95%A9%EC%84%B1-%EC%BB%B4%ED%8F%AC%EB%84%8C%ED%8A%B8-%EB%A7%8C%EB%93%A4%EA%B8%B0\\">(\ud55c\uad6d\uc5b4 \ubc88\uc5ed)</a></p><p data-notion-block-id=\\"2e6e548d-8a8e-8086-86c5-d03f3af70716\\">Compound \ud328\ud134 \ub300\uc2e0 (type-safe\ub97c \ubaa9\ud45c\ub85c \ud55c\ub2e4\uba74) props\ub098 slot\uc744 \uc0ac\uc6a9\ud558\ub294 \uac83\uc774 \uc88b\uc740 \uacbd\uc6b0\ub3c4 \uc788\ub2e4\ub294 \uac83\uacfc(Spotify\uc758 <a href=\\"https://ones-to-watch.ethansup.net/news/post/f51019e1-e38c-4b60-a636-aab2334f6e8b#db3ef69e-93d7-422a-a3e0-d5816a79be50\\">\uc9c4\ud654\ud558\ub294 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c</a> \uae00 \ucc98\ub7fc\uc694) Type\uc744 \ub123\uc5b4\uc11c \ub9cc\ub4e4 \uc218 \uc788\ub294 Compound Factory pattern\ub3c4 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ud754\ud55c \ud328\ud134\uc740 \uc544\ub2c8\uc9c0\ub9cc, type-safe\ud55c \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc744 \ub9cc\ub4e4\uae30\uc5d0\ub294 \uc774 \ubc29\uc2dd\uc774 \uc88b\uc744 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4(\ud639\uc740 \ub7ec\ub2dd\ucee4\ube0c\ub54c\ubb38\uc5d0 \ucd94\ucc9c\ub418\uc9c0 \uc54a\uc744\uc9c0\ub3c4\uc694).</p><h2 data-notion-block-id=\\"2e7e548d-8a8e-805f-94ba-c7061aa3d3e5\\" id=\\"2e7e548d-8a8e-805f-94ba-c7061aa3d3e5\\">React \ucf54\ub4dc \ub9ac\ubc84\uc2a4 \uc5d4\uc9c0\ub2c8\uc5b4\ub9c1</h2><a href=\\"https://fant.io/react/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://fant.io/react/</a><p data-notion-block-id=\\"2e7e548d-8a8e-803a-9e54-f0d128dac969\\">React production \ucf54\ub4dc\ub97c \uc5b4\ub5bb\uac8c inspect\ud560 \uc218 \uc788\ub294\uc9c0 React\uc758 \uc791\ub3d9\ubc29\uc2dd\uacfc \ud568\uaed8 \ucc28\uadfc\ucc28\uadfc \uc54c\uc544\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4. \uc644\ubcbd\ud558\uac8c \ubaa8\ub450 \ubd84\uc11d\ud558\uc9c0\ub294 \ubabb\ud558\uc9c0\ub9cc, Fiber\uacfc \ud568\uaed8 \ucf54\ub4dc\ub97c \uc8fc\uba74 minify\ub41c \uc18c\uc2a4\ucf54\ub4dc\ub3c4 \ubcf4\uae30 \uc27d\uac8c \ubc14\uafd4\uc8fc\ub294\uac8c \uc778\uc0c1\uc801\uc774\ub124\uc694. uglify\uac00 \uc774\uc81c\ub294 \uc758\ubbf8\uac00 \uc5c6\uc5b4\uc9c8\ub3c4\uc694.</p><h2 data-notion-block-id=\\"2e7e548d-8a8e-80c6-b145-e2b80e917782\\" id=\\"2e7e548d-8a8e-80c6-b145-e2b80e917782\\">\uc5f0\ud569 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc774 \uc2e4\ud328\ud588\ub2e4. \uc65c\uc77c\uae4c?</h2><a href=\\"https://www.shaunbent.co.uk/blog/why-federated-design-systems-keep-failing/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.shaunbent.co.uk/blog/why-federated-design-systems-keep-failing/</a><p data-notion-block-id=\\"2e7e548d-8a8e-80e6-90b2-c8d5742e6de0\\">Spotify\ub294 Encore\ub77c\ub294 Base \ub514\uc790\uc778\uc2dc\uc2a4\ud15c\ubd80\ud130 \uc2dc\uc791\ud574\uc11c \uac01\uc790\uc758 \ud300\uc5d0 \ub9de\uac8c \ub514\uc790\uc778\uc2dc\uc2a4\ud15c\uc744 \ud655\uc7a5\ud574 \ub098\uac00\ub294 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc744 \uc18c\uac1c\ud558\uace0 \uc0ac\uc6a9\ud558\ub294 \uac83\uc744 \ubc1c\ud45c\ud588\uc2b5\ub2c8\ub2e4(<a href=\\"https://www.figma.com/blog/creating-coherence-how-spotifys-design-system-goes-beyond-platforms/\\">Encore \uc18c\uac1c</a>). \uc5c4\uccad\ub098\uac8c \ud070 \ud68c\uc0ac\uc5d0\uc11c \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc5d0\uc11c \uc5f0\ud569\ud615 \uc811\uadfc \ubc29\uc2dd\uc744 \uc5b4\ub5bb\uac8c \uc801\uc6a9\ud588\ub294\uc9c0 \uc18c\uac1c\ud558\uace0, \uc65c \uc774\uac83\uc774 \uc2e4\ud328\ud588\ub294\uc9c0 \ud68c\uace0\ud558\ub294 \uccab\ubc88\uc9f8 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2e6e548d-8a8e-8093-9a60-d7c1e2fc0007\\" id=\\"2e6e548d-8a8e-8093-9a60-d7c1e2fc0007\\">TypeScript \ucf54\ub4dc\ubca0\uc774\uc2a4\uac00 \ucee4\uc84c\uc744 \ub54c</h2><a href=\\"https://www.joshribakoff.com/blog/lint-snapshots/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.joshribakoff.com/blog/lint-snapshots/</a><p data-notion-block-id=\\"2e6e548d-8a8e-80ac-a56f-d8879b00bc5b\\">\ud558\ub098\uc758 TypeScript \ucf54\ub4dc\ubca0\uc774\uc2a4\uac00 \ucee4\uc84c\uc744 \ub54c \uc5b4\ub290 \ucf54\ub4dc\ubca0\uc774\uc2a4\uc758 \uc608\uc678\ucc98\ub9ac, \ub9b0\ud2b8 \ub8f0 \ub044\uae30\ub97c \uc5b4\ub5bb\uac8c \ub2e4\ub8e8\uc5c8\ub294\uc9c0 \uac04\ub2e8\ud558\uac8c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc0c8 \ud30c\uc77c\uc774\ub098 \ucf54\ub4dc\uac00 \uc0dd\uc131\ub418\uc5c8\uc744 \ub54c CODEOWNER\ub97c \uae30\ubc18\uc73c\ub85c \ub2f4\ub2f9\uc790\ub97c \uc9c0\uc815\ud558\ub294 \uac83\uc774 \uc778\uc0c1\uc801\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2e7e548d-8a8e-80ae-b718-d72029cc8836\\" id=\\"2e7e548d-8a8e-80ae-b718-d72029cc8836\\"><code>Array</code> / <code>TypedArray</code>\uc640 <code>Object</code>, \uadf8\ub9ac\uace0 \uc131\ub2a5</h2><a href=\\"https://www.royalbhati.com/posts/js-array-vs-typedarray\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.royalbhati.com/posts/js-array-vs-typedarray</a><p data-notion-block-id=\\"2e7e548d-8a8e-8081-9865-fa1dedb668ca\\">Array\uc640 TypedArray, Object\ub97c \uae30\ubc18\uc73c\ub85c <a href=\\"https://ones-to-watch.ethansup.net/news/post/8b8e4348-60f9-477e-9892-e7dfdf611fe0#b0fa8093-7010-49bd-9e12-b95e81fcacef\\">Monomorphism</a>\uacfc TypedArray\ub294 \uc5b4\ub5a4 \uc7a5\uc810\uc774 \uc788\ub294\uc9c0, \uc774\uc678\uc5d0\ub3c4 \uc5ec\ub7ec\uac00\uc9c0 \ud560\ub2f9 \ubc29\uc2dd\uc758 \ucc28\uc774, \uce90\uc2dc\uc5d0 \ub300\ud55c \uc815\ubcf4\ub3c4 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"2dbe548d-8a8e-80da-b13f-ed761bb77949\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"2e7e548d-8a8e-80c1-9752-d52b2a323e87\\" id=\\"2e7e548d-8a8e-80c1-9752-d52b2a323e87\\">AST \uae30\ubc18 \uc544\ud0a4\ud14d\uccd0, \uadf8 \ub2e4\uc74c\uc740?</h2><a href=\\"https://marvinh.dev/blog/signals-vs-query-based-compilers/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://marvinh.dev/blog/signals-vs-query-based-compilers/</a><p data-notion-block-id=\\"2e7e548d-8a8e-8032-9bfb-c996d5b0ef88\\">\uc61b\ub0a0\uc5d0\ub294 AST\ub85c \ubd84\uc11d\ud574\uc11c \ucef4\ud30c\uc77c\ub9c1 \ud588\uc5c8\uc9c0\ub9cc, \ucd5c\uadfc\uc5d0\ub294 \ucffc\ub9ac \uae30\ubc18 \ucef4\ud30c\uc77c(\ubcf4\ud1b5 LSP\uc5d0 \uc0ac\uc6a9\ub428), Signal \uae30\ubc18 \ucef4\ud30c\uc77c\ub85c \ubc14\ub00c\uc5c8\uc2b5\ub2c8\ub2e4. \uc774 \ub54c \ucffc\ub9ac \uae30\ubc18 \ucef4\ud30c\uc77c\uacfc Signal \uae30\ubc18 \ucef4\ud30c\uc77c\uc740 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2e7e548d-8a8e-8008-9c7b-dbe22adda6f4\\" id=\\"2e7e548d-8a8e-8008-9c7b-dbe22adda6f4\\">\uac04\ub2e8\ud55c CSS starter</h2><a href=\\"https://meiert.com/blog/a-minimal-css-starter/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://meiert.com/blog/a-minimal-css-starter/</a><p data-notion-block-id=\\"2e7e548d-8a8e-80c8-a501-d9ab5cefbd79\\">CSS reset\ub300\uc2e0, \uac04\ub2e8\ud558\uac8c \ube0c\ub77c\uc6b0\uc800\uc758 \uae30\ubcf8\uac12\uc744 \ud65c\uc6a9\ud558\ub418 \uc788\uc73c\uba74 \uc720\uc6a9\ud55c CSS \uae30\ub2a5\uc744 \uc0ac\uc6a9\ud55c starter\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2e7e548d-8a8e-80f7-80f7-dc9b60d28018\\" id=\\"2e7e548d-8a8e-80f7-80f7-dc9b60d28018\\">\ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc758 \uac00\uce58\ub294 \uad6c\ud604\uc5d0\uc11c \uc628\ub2e4</h2><a href=\\"https://www.shaunbent.co.uk/blog/is-there-too-much-design-in-design-systems/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.shaunbent.co.uk/blog/is-there-too-much-design-in-design-systems/</a><p data-notion-block-id=\\"2e7e548d-8a8e-8027-b57c-c2919f753c9c\\">\ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc744 \uad6c\ud604\ud558\ub294 \ub514\uc790\uc774\ub108\uc640 \uac1c\ubc1c\uc790\uc758 \ube44\uc728\uc5d0\uc11c \ub514\uc790\uc774\ub108\uac00 \ub9ce\uac8c \ub418\uba74 \uc5b4\ub5a4 \uc77c\uc774 \uc77c\uc5b4\ub098\uac8c \ub418\ub294\uc9c0 \uc18c\uac1c\ud558\uace0, \uadf8\ub9ac\uace0 \uc65c \uc774 \uc77c\uc774 \uc77c\uc5b4\ub098\ub294\uc9c0 \ubd84\uc11d\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2e7e548d-8a8e-8038-b044-de4196e27495\\" id=\\"2e7e548d-8a8e-8038-b044-de4196e27495\\"><code>for...of</code> vs <code>forEach</code></h2><a href=\\"https://waspdev.com/articles/2026-01-01/javascript-for-of-loops-are-actually-fast\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://waspdev.com/articles/2026-01-01/javascript-for-of-loops-are-actually-fast</a><p data-notion-block-id=\\"2e7e548d-8a8e-80ce-bac8-dfe820e91145\\"><code>for...of</code>\uad6c\ubb38\uacfc <code>for</code>, <code>for...in</code>, <code>forEach</code>\ubb38\uc744 \uac04\ub2e8\ud558\uac8c \ubca4\uce58\ub9c8\ud06c\ud55c \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2e7e548d-8a8e-8056-bf65-f25d8a8ba4be\\" id=\\"2e7e548d-8a8e-8056-bf65-f25d8a8ba4be\\">Chrome devtools \ud301</h2><a href=\\"https://calendar.perfplanet.com/2025/chrome-devtools-all-the-time/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://calendar.perfplanet.com/2025/chrome-devtools-all-the-time/</a><h2 data-notion-block-id=\\"2e5e548d-8a8e-8024-b13b-eed1028c9b0f\\" id=\\"2e5e548d-8a8e-8024-b13b-eed1028c9b0f\\">MFE\uc5d0\uc11c \uc804\uc5ed \uc0c1\ud0dc\ub97c \ub450\uba74 \uc548\ub41c\ub2e4.</h2><a href=\\"https://lucamezzalira.medium.com/global-state-in-micro-frontends-no-thanks-942f6f7b5c36\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://lucamezzalira.medium.com/global-state-in-micro-frontends-no-thanks-942f6f7b5c36</a><p data-notion-block-id=\\"2e7e548d-8a8e-806f-817a-cf01cb6e616f\\">MFE\uc5d0\uc11c \uc804\uc5ed \uc0c1\ud0dc\ub97c \ub450\uba74 \uc548\ub418\ub294 \uc774\uc720\uc640 \uadf8 \ub300\uc548\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2e7e548d-8a8e-80ff-a4d8-c4141a0daa5a\\" id=\\"2e7e548d-8a8e-80ff-a4d8-c4141a0daa5a\\">TypeScript \ucd94\ub860 \uc2dc\uac04 \ucd94\uc801\ud558\uae30</h2><a href=\\"https://www.viget.com/articles/fixing-typescript-performance-problems\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.viget.com/articles/fixing-typescript-performance-problems</a><h2 data-notion-block-id=\\"2e1e548d-8a8e-80df-8b9e-d4d736179b1d\\" id=\\"2e1e548d-8a8e-80df-8b9e-d4d736179b1d\\">React Compiler\ub294 \uc5b4\ub5a4 \uacfc\uc815\uc744 \uac70\uccd0 \ucd5c\uc801\ud654\ub97c \ud560\uae4c</h2><a href=\\"https://gitnation.com/contents/react-compiter-internals\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://gitnation.com/contents/react-compiter-internals</a><h2 data-notion-block-id=\\"2e1e548d-8a8e-8046-bb6c-d32acc4fff3a\\" id=\\"2e1e548d-8a8e-8046-bb6c-d32acc4fff3a\\">React\uc5d0\uc11c\uc758 \uba40\ud2f0\uc2a4\ub808\ub529 \ub3c4\uc785 \ubc29\uc2dd \uc18c\uac1c</h2><a href=\\"https://gitnation.com/contents/scaling-react-apps-with-parallelism-patterns-for-multi-threaded-uis\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://gitnation.com/contents/scaling-react-apps-with-parallelism-patterns-for-multi-threaded-uis</a><h2 data-notion-block-id=\\"2e7e548d-8a8e-801c-9147-d2d6d29c030c\\" id=\\"2e7e548d-8a8e-801c-9147-d2d6d29c030c\\"><code>useEffectEvent</code>\uc740 \ubb34\uc5c7\uc744 \ud574\uacb0\ud558\uace0\uc790 \ub098\uc654\uc744\uae4c</h2><a href=\\"https://blog.logrocket.com/react-has-finally-solved-its-biggest-problem-useeffectevent/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.logrocket.com/react-has-finally-solved-its-biggest-problem-useeffectevent/</a><h2 data-notion-block-id=\\"2e7e548d-8a8e-80fb-a289-dd24dd697f33\\" id=\\"2e7e548d-8a8e-80fb-a289-dd24dd697f33\\">Static Heremes\ub97c \ud1b5\ud574 JS\ub97c C\ub85c \ucef4\ud30c\uc77c \ud558\uae30</h2><a href=\\"https://devongovett.me/blog/static-hermes.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://devongovett.me/blog/static-hermes.html</a><h1 data-notion-block-id=\\"2dbe548d-8a8e-8083-91b0-d2c8e0e3d808\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://logtape.org/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://logtape.org/</a><p data-notion-block-id=\\"2e7e548d-8a8e-80af-9bfa-c9ca85f86050\\">Pino\ub098 winston\ub300\uc2e0 \uc0ac\uc6a9\ud560 \uc218 \uc788\uace0 \uc5ec\ub7ec \ub2e4\ub978 \ud50c\ub7ab\ud3fc\uc774\ub098 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc5d0 \ud1b5\ud569\uc774 \uc26c\uc6b4 \ub85c\uae45 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc785\ub2c8\ub2e4.</p><a href=\\"https://webkit.org/blog/17660/introducing-css-grid-lanes/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://webkit.org/blog/17660/introducing-css-grid-lanes/</a><p data-notion-block-id=\\"2e7e548d-8a8e-8097-aba7-f29c30cdddb8\\">Masonry layout\uc744 \uad6c\ud604\ud55c <code>display: grid-lane;</code>\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://fate.technology/posts/introducing-fate\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://fate.technology/posts/introducing-fate</a><p data-notion-block-id=\\"2e5e548d-8a8e-805d-b60c-f75ee2272b56\\">GraphQL\uacfc Relay\uc5d0 \uc601\uac10\uc744 \ubc1b\uc740 tRPC \ud074\ub77c\uc774\uc5b8\ud2b8 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc785\ub2c8\ub2e4.</p><p data-notion-block-id=\\"2e5e548d-8a8e-804e-a46e-d39970510ced\\"></p>"}')}}]);